UPDATE tb_course_sessions
   SET status = #{to},
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND status = #{from}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM tb_attendance_records
     WHERE course_id = #{courseId}
    UNION ALL
    SELECT 1
      FROM tb_attendance_qr_tokens qt
      JOIN tb_course_sessions cs ON cs.id = qt.session_id
     WHERE cs.course_id = #{courseId}
)

SELECT EXISTS (
    SELECT 1 FROM tb_course_sessions
     WHERE course_id = #{courseId}
       AND status != 'SCHEDULED'
)

